function readClaudeEnvConfig() {
  let baseUrl = process.env.ANTHROPIC_BASE_URL ?? "";
  let authToken = process.env.ANTHROPIC_AUTH_TOKEN ?? "";
  try {
    const p3 = join23(homedir7(), ".claude", "settings.json");
    if (existsSync11(p3)) {
      const s = JSON.parse(readFileSync14(p3, "utf8"));
      const e6 = s?.env ?? {};
      if (!baseUrl && typeof e6.ANTHROPIC_BASE_URL === "string") baseUrl = e6.ANTHROPIC_BASE_URL;
      if (!authToken && typeof e6.ANTHROPIC_AUTH_TOKEN === "string") authToken = e6.ANTHROPIC_AUTH_TOKEN;
    }
  } catch {
  }
  return { baseUrl, authToken };
}
function isGatewayRouted() {
  const { baseUrl, authToken } = readClaudeEnvConfig();
  return /parallight/i.test(baseUrl) || authToken.startsWith("plk_");
}
function gatewayProbeToken() {
  try {
    const a6 = loadAuth();
    if (a6?.proxy_token) return a6.proxy_token;
  } catch {
  }
  const { authToken } = readClaudeEnvConfig();
  return authToken.startsWith("plk_") ? authToken : null;
}
async function fetchConfiguredProviders() {
  const token = gatewayProbeToken();
  if (!token) return null;
  try {
    const res = await fetch(`${LLM_PROXY_URL}/v1/providers`, {
      headers: { authorization: `Bearer ${token}` }
    });
    if (!res.ok) return null;
    const j7 = await res.json();
    return j7 && typeof j7.providers === "object" ? j7.providers : null;
  } catch {
    return null;
  }
}
